<script setup>
import PageHeader from '../components/PageHeader.vue'; import { useLibraryStore } from '../stores/library'
import { useLocale } from '../i18n.js'
const library = useLibraryStore()
const { t, l } = useLocale()
const formatSize = (bytes) => bytes < 1048576 ? `${Math.max(1, Math.round(bytes / 1024))} KB` : `${(bytes / 1048576).toFixed(1)} MB`
const formatTime = (value) => new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(value))
</script>
<!-- recentAssets 已在 Pinia 中按上传时间倒序并限制为 12 个。 -->
<template><section class="workspace-page recent-page"><PageHeader :title="t.recent" :description="`${t.latestUpload} · ${library.recentAssets.length}`"/><div v-if="library.recentAssets.length" class="recent-list"><article v-for="asset in library.recentAssets" :key="asset.id" class="recent-item"><div class="recent-thumb"><img v-if="asset.type === 'image'" :src="asset.url" :alt="asset.name"><span v-else>▶</span></div><div class="recent-details"><b>{{ asset.name }}</b><small>{{ library.storeById(asset.storeId)?.name || '-' }} · {{ formatSize(asset.size) }}</small><time>{{ t.uploadTime }}：{{ formatTime(asset.createdAt) }}</time></div><button class="danger recent-delete" @click="library.moveToTrash(asset.id)">{{ t.moveTrash }}</button></article></div><div v-else class="empty ui-empty"><svg class="empty-illustration" viewBox="0 0 160 128" aria-hidden="true"><ellipse cx="80" cy="116" rx="48" ry="6" fill="#eef4fb"/><path d="m36 64 44-18 44 18-44 20Z" fill="#c5ddf9"/><path d="m36 64 44 20v34l-44-20Z" fill="#dbeafd"/><path d="m80 84 44-20v34l-44 20Z" fill="#a8cdf7"/><path d="m36 64-16 20 45 17 15-17Z" fill="#eef5ff" stroke="#d3e5fa"/><path d="m80 84 16 17 44-19-16-18Z" fill="#e1efff" stroke="#c5ddf9"/><rect x="58" y="12" width="36" height="34" rx="6" transform="rotate(-12 58 12)" fill="#e7f1fe"/><path d="m63 36 8-11 8 7 5-6 9 12" fill="#a8cdf7"/><circle cx="85" cy="18" r="3" fill="#bad6f7"/><path d="M110 18v-8m13 16 6-6" stroke="#1677ef" stroke-width="3" stroke-linecap="round"/><circle cx="32" cy="46" r="3" fill="#c5ddf9"/></svg><h2>{{ l('暂无上传记录','No uploads yet','ยังไม่มีรายการอัปโหลด') }}</h2><p>{{ l('上传的素材会显示在这里。','Your uploaded media will appear here.','สื่อที่อัปโหลดจะแสดงที่นี่') }}</p></div></section></template>
